    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # The colored horizontal run is the pattern to copy.
    best = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if c - start > len(best):
                best = [(r, start+i, row[start+i]) for i in range(c-start)]
    pattern_colors = {v for _, _, v in best}
    markers = [(r,c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] not in pattern_colors]
    out = [row[:] for row in grid]
    mid = len(best)//2
    for r,c in markers:
        for i, (_, _, v) in enumerate(best):
            x = c + i - mid
            if 0 <= x < w:
                out[r][x] = v
    return out
